using Dabbler.Api.Querying;
using Dabbler.Security.Authorization;
using T3ApiNs.Services;
using T4DtoNs;
using Microsoft.AspNetCore.Mvc;

namespace T3ApiNs.Controllers;

/// <summary>
/// CRUD + grid-query controller for the <see cref="T1EntityDto"/> aggregate.
/// Generated by the dabbler-crud-service template. The auth attributes
/// (<see cref="DabblerEndpointAuthorizeAttribute"/>) run before action method bodies, so
/// mutations are only reached after the policy check passes.
/// </summary>
[ApiController]
[Route("api/[controller]")]
public class T2EntityPluralController : ControllerBase
{
    private readonly IT1EntityService _service;

    public T2EntityPluralController(IT1EntityService service)
    {
        _service = service;
    }

    /// <summary>
    /// QBE grid query: composite filter (recursive AND/OR), multi-column sort, paging.
    /// POST (not GET) because nested filter graphs do not round-trip through query-string encoding.
    /// </summary>
    [HttpPost("query")]
    [DabblerEndpointAuthorize("QueryTplAuthPrefix")]
    public async Task<ActionResult<GridQueryResponse<T1EntityDto>>> QueryAsync(
        [FromBody] GridQueryRequest request,
        CancellationToken cancellationToken)
    {
        var response = await _service.QueryAsync(request, cancellationToken);
        return Ok(response);
    }

    [HttpGet("{idT10PkRoute}")]
    [DabblerEndpointAuthorize("GetTplAuthPrefix")]
    public async Task<ActionResult<T1EntityDto>> GetByIdAsync(
        T9PkType id,
        CancellationToken cancellationToken)
    {
        var dto = await _service.GetByIdAsync(id, cancellationToken);
        return dto is null ? NotFound() : Ok(dto);
    }

    [HttpPost]
    [DabblerEndpointAuthorize("CreateTplAuthPrefix")]
    public async Task<ActionResult<T1EntityDto>> CreateAsync(
        [FromBody] T1EntityDto dto,
        CancellationToken cancellationToken)
    {
        var created = await _service.CreateAsync(dto, cancellationToken);
        return Ok(created);
    }

    [HttpPut("{idT10PkRoute}")]
    [DabblerEndpointAuthorize("UpdateTplAuthPrefix")]
    public async Task<ActionResult<T1EntityDto>> UpdateAsync(
        T9PkType id,
        [FromBody] T1EntityDto dto,
        CancellationToken cancellationToken)
    {
        var updated = await _service.UpdateAsync(id, dto, cancellationToken);
        return updated is null ? NotFound() : Ok(updated);
    }

    [HttpDelete("{idT10PkRoute}")]
    [DabblerEndpointAuthorize("DeleteTplAuthPrefix")]
    public async Task<IActionResult> DeleteAsync(
        T9PkType id,
        CancellationToken cancellationToken)
    {
        return await _service.DeleteAsync(id, cancellationToken) ? NoContent() : NotFound();
    }
}
